#!/bin/sh
set -e

# ── Provisioning accounting — READ THIS BEFORE ADDING AN `exit 1` ──────
# This script is the container ENTRYPOINT and its last line is `exec maddy`.
# It therefore must NOT exit non-zero when provisioning fails: that would kill
# the mail server outright and turn "one mailbox did not get created" into a
# total mail outage — strictly worse than the bug being fixed. So the verdict
# is EMITTED here, never enforced here:
#   * a machine-readable SUMMARY line on stdout (docker logs maddy), and
#   * the same line, plus per-item detail, written to $PROV_RECEIPT inside the
#     maddy_data volume and stamped with the epoch it was written at.
# The ASSERTION lives where it can fail safely: configs/assert-provisioning.sh,
# wired as build.json#compose.post_hook. It runs on the VM after compose-up,
# reads this receipt and turns the SHIP red while maddy keeps serving mail.
# That post-hook is itself covered by the ship engine's revision-scoped
# receipt, so "the assertion never ran" is not a green outcome either.
#
# Counts live in FILES, not shell variables: `prov` runs its command inside a
# command substitution, and an incremented counter in a subshell is discarded
# on exit — literally how a loop counts failures and then reports none.
PROV_RECEIPT=/data/.provisioning-summary
rm -f "$PROV_RECEIPT"
TALLY_DIR=$(mktemp -d /tmp/.maddy-init-tally.XXXXXX)
tally()       { echo "$2" >> "$TALLY_DIR/$1"; }
# `cat | wc -l`, not `wc -l < file`: the redirection of a missing tally file is
# the SHELL's error, not wc's, so `2>/dev/null` on wc does not suppress it and
# every zero count printed a spurious "No such file or directory".
tally_count() { _c=$(cat "$TALLY_DIR/$1" 2>/dev/null | wc -l | tr -d ' '); echo "${_c:-0}"; }

# prov <tally-base> <label> <command...>
#
# maddy's create verbs are NOT idempotent: `creds create`, `imap-acct create`
# and `imap-mboxes create` each error when the object already exists, and that
# is the NORMAL path on every boot after the first. That is why every generated
# line used to end in `|| true` — and why a genuine failure (locked
# credentials.db, a password that never got injected, version skew) was
# indistinguishable from a healthy no-op and vanished into a green ship. The
# same silent divergence between this store and Stalwart's is what left four
# declared accounts non-existent for a day while the MX accepted their mail.
#
# So classify instead of swallowing: an "already exists" error is an `_exists`
# tally, anything else is a `_failed` tally the SUMMARY will report. Always
# returns 0 — that is the `exec maddy` constraint expressed in code, not an
# oversight.
prov() {
  _t=$1; _l=$2; shift 2
  if _out=$("$@" 2>&1); then
    [ -n "$_out" ] && printf '%s\n' "$_out" | sed "s|^|  [$_l] |"
    tally "${_t}_ok" "$_l"
    return 0
  else
    _rc=$?
  fi
  [ -n "$_out" ] && printf '%s\n' "$_out" | sed "s|^|  [$_l] |"
  case "$_out" in
    *"already exist"*|*"already in use"*|*exists*)
      tally "${_t}_exists" "$_l"
      return 0
      ;;
  esac
  echo "[init] PROVISIONING FAILURE ($_l): exit $_rc" >&2
  tally "${_t}_failed" "$_l (exit $_rc)"
  return 0
}

# Install jq + sqlite3 — required by:
#   /usr/local/bin/mail-sieve-subset-delivery-time (jq for per-message rule eval)
#   /usr/local/bin/mail-sieve-subset-post-hoc      (jq + sqlite3 for batch ops)
# Idempotent — no-op if already present (alpine apk).
for pkg in jq sqlite; do
  if ! command -v "${pkg%sqlite}sqlite3" >/dev/null 2>&1 && ! command -v "$pkg" >/dev/null 2>&1; then
    echo "[init] Installing $pkg..."
    apk add --no-cache "$pkg" >/dev/null 2>&1 || true
  fi
done

echo "[init] Generating maddy.conf from template..."
# maddy.conf uses native `{env:VAR}` interpolation for secrets — no sed,
# no shell-text mangling. Maddy reads env vars at config-load time.
# Source of every secret value: src/secrets.yaml -> env_file (.secrets) -> $env.
cp /etc/maddy/maddy.conf.tpl /data/maddy.conf

# Write DKIM private key from base64
if [ -n "$DKIM_PRIVATE_KEY_B64" ]; then
  echo "[init] Writing DKIM key..."
  mkdir -p /data/dkim
  echo "$DKIM_PRIVATE_KEY_B64" | base64 -d > /data/dkim/diegonmarcos.com.key
  chmod 600 /data/dkim/diegonmarcos.com.key
fi

# Create accounts AND sync passwords on every boot.
# `creds create` errors if the account exists, so an existing account would
# keep a stale password forever (drift between secrets.yaml and the maddy
# credentials.db). Pair with `creds password` to UPSERT the secret —
# `creds create` for first-boot, `creds password` for password rotation.
# Pipe passwords via stdin — never `--password $VAR` (the value would land in
# process args / `docker top` / `ps` output). maddy's own --help carries the
# same warning. Source of every value is sops-encrypted src/secrets.yaml,
# which docker compose injects as env_file -> $ME_PASSWORD / $NOREPLY_PASSWORD.
#
# `printf '%s'` (no trailing \n) — `echo` would append a newline that maddy
# then bcrypts into the stored hash, so SMTP clients sending the bare value
# would never authenticate.
#
# Stderr stays visible so that any `creds password` failure (locked db,
# missing config block, version skew) shows up in `docker logs maddy`.
# `creds create` is expected to error on existing accounts — that's fine,
# `creds password` is the unconditional upsert.
echo "[init] Ensuring accounts + syncing passwords..."
# USER_CREATION_BLOCK below — generated from build.json#users at flake build time.
# Each entry produces: creds create + creds password + imap-acct create.
# Source: aa-sui_tools-maddy/build.json#users (this service's own SoT).
prov accounts 'creds:create 42'   maddy creds create   -p "$MAIL_DEFAULT_PASSWORD" 42@diegonmarcos.com
prov users    'creds:password 42' maddy creds password -p "$MAIL_DEFAULT_PASSWORD" 42@diegonmarcos.com
prov imap     'imap-acct 42'      maddy imap-acct create 42@diegonmarcos.com
prov accounts 'creds:create me'   maddy creds create   -p "$ME_PASSWORD" me@diegonmarcos.com
prov users    'creds:password me' maddy creds password -p "$ME_PASSWORD" me@diegonmarcos.com
prov imap     'imap-acct me'      maddy imap-acct create me@diegonmarcos.com
prov accounts 'creds:create admin'   maddy creds create   -p "$ADMIN_PASSWORD" admin@diegonmarcos.com
prov users    'creds:password admin' maddy creds password -p "$ADMIN_PASSWORD" admin@diegonmarcos.com
prov imap     'imap-acct admin'      maddy imap-acct create admin@diegonmarcos.com
prov accounts 'creds:create no-reply'   maddy creds create   -p "$NOREPLY_PASSWORD" no-reply@diegonmarcos.com
prov users    'creds:password no-reply' maddy creds password -p "$NOREPLY_PASSWORD" no-reply@diegonmarcos.com
prov imap     'imap-acct no-reply'      maddy imap-acct create no-reply@diegonmarcos.com
prov accounts 'creds:create yo'   maddy creds create   -p "$MAIL_DEFAULT_PASSWORD" yo@diegonmarcos.com
prov users    'creds:password yo' maddy creds password -p "$MAIL_DEFAULT_PASSWORD" yo@diegonmarcos.com
prov imap     'imap-acct yo'      maddy imap-acct create yo@diegonmarcos.com

# FOLDER_CREATION_BLOCK below — the F0 sender-classification folders
